/**
 * useOrbStreaming — SSE streaming + sentence-level TTS pipelining for DashOrb
 *
 * Replaces the old `stream: false` → fake typewriter approach with:
 * 1. Real SSE streaming from ai-proxy (text appears as Claude generates it)
 * 2. Sentence-level TTS pipelining (Dash starts speaking sentence 1 while
 *    sentence 2 is still being generated by the AI)
 * 3. Phoneme-estimated viseme IDs (much better than random cycling)
 *
 * ≤200 lines (WARP.md hook limit).
 */

import { useCallback, useRef } from 'react';
import { assertSupabase } from '@/lib/supabase';
import { estimateVisemeTimeline, type VisemeEvent } from '@/lib/voice/visemeEstimator';

// ── Types ───────────────────────────────────────────────────────────────

export interface StreamingCallbacks {
  /** Called with each text chunk as it arrives from SSE */
  onTextChunk: (chunk: string, accumulated: string) => void;
  /** Called when a complete sentence is ready for TTS */
  onSentenceReady: (sentence: string, index: number) => void;
  /** Called with estimated viseme events for the current TTS sentence */
  onVisemeEvent: (event: VisemeEvent) => void;
  /** Called when the full response is complete */
  onComplete: (fullText: string) => void;
  /** Called on error */
  onError: (error: Error) => void;
}

export interface StreamingRequest {
  endpoint: string;
  body: Record<string, unknown>;
  accessToken: string;
}

// ── Sentence splitter ───────────────────────────────────────────────────

const SENTENCE_END = /([.!?])\s+/;

function extractCompleteSentences(buffer: string): { sentences: string[]; remainder: string } {
  const sentences: string[] = [];
  let rest = buffer;

  // eslint-disable-next-line no-constant-condition
  while (true) {
    const match = SENTENCE_END.exec(rest);
    if (!match) break;

    const end = match.index + match[1].length;
    const sentence = rest.slice(0, end).trim();
    if (sentence.length > 0) sentences.push(sentence);
    rest = rest.slice(end).trimStart();
  }

  return { sentences, remainder: rest };
}

// ── Hook ────────────────────────────────────────────────────────────────

export function useOrbStreaming() {
  const abortRef = useRef<AbortController | null>(null);
  const isStreamingRef = useRef(false);

  /**
   * Stream a response from ai-proxy via SSE and pipe sentences to TTS
   * as they complete (instead of waiting for the full response).
   */
  const streamResponse = useCallback(
    async (request: StreamingRequest, callbacks: StreamingCallbacks) => {
      // Cancel any in-flight stream
      abortRef.current?.abort();
      const controller = new AbortController();
      abortRef.current = controller;
      isStreamingRef.current = true;

      let accumulated = '';
      let sentenceBuffer = '';
      let sentenceIndex = 0;

      try {
        const response = await fetch(request.endpoint, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${request.accessToken}`,
          },
          body: JSON.stringify({ ...request.body, stream: true }),
          signal: controller.signal,
        });

        if (!response.ok) {
          throw new Error(`Streaming failed: ${response.status}`);
        }

        // React Native may not support ReadableStream — fall back to full text
        const isRN =
          typeof navigator !== 'undefined' && navigator.product === 'ReactNative';
        const canStream =
          !isRN && response.body && typeof response.body.getReader === 'function';

        const processLine = (line: string) => {
          if (!line.startsWith('data: ')) return;
          const data = line.slice(6).trim();
          if (data === '[DONE]') return;
          try {
            const parsed = JSON.parse(data);
            const text =
              parsed?.delta?.text ??
              parsed?.choices?.[0]?.delta?.content ??
              '';
            if (!text) return;

            accumulated += text;
            sentenceBuffer += text;
            callbacks.onTextChunk(text, accumulated);

            // Extract complete sentences and fire TTS for each
            const { sentences, remainder } = extractCompleteSentences(sentenceBuffer);
            sentenceBuffer = remainder;

            for (const sentence of sentences) {
              callbacks.onSentenceReady(sentence, sentenceIndex);

              // Estimate viseme timeline for this sentence and fire events
              const timeline = estimateVisemeTimeline(sentence);
              for (const evt of timeline) {
                // Schedule viseme at the estimated offset
                setTimeout(() => {
                  if (isStreamingRef.current || sentenceIndex > 0) {
                    callbacks.onVisemeEvent(evt);
                  }
                }, evt.offsetMs);
              }

              sentenceIndex++;
            }
          } catch {
            // Skip malformed SSE lines
          }
        };

        if (canStream) {
          const reader = response.body!.getReader();
          const decoder = new TextDecoder('utf-8');
          let buffer = '';

          // eslint-disable-next-line no-constant-condition
          while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            buffer += decoder.decode(value, { stream: true });
            const lines = buffer.split('\n');
            buffer = lines.pop() || '';
            for (const line of lines) processLine(line);
          }
          // Process any remaining buffer
          if (buffer) processLine(buffer);
        } else {
          // RN fallback: read full text then parse SSE lines
          const sseText = await response.text();
          for (const line of sseText.split('\n')) processLine(line);
        }

        // Flush remaining text as final sentence
        if (sentenceBuffer.trim()) {
          callbacks.onSentenceReady(sentenceBuffer.trim(), sentenceIndex);
          const timeline = estimateVisemeTimeline(sentenceBuffer.trim());
          for (const evt of timeline) {
            setTimeout(() => callbacks.onVisemeEvent(evt), evt.offsetMs);
          }
        }

        callbacks.onComplete(accumulated);
      } catch (err) {
        if ((err as Error).name !== 'AbortError') {
          callbacks.onError(err instanceof Error ? err : new Error(String(err)));
        }
      } finally {
        isStreamingRef.current = false;
      }
    },
    [],
  );

  /** Cancel any in-flight stream */
  const cancelStream = useCallback(() => {
    abortRef.current?.abort();
    isStreamingRef.current = false;
  }, []);

  return { streamResponse, cancelStream };
}
